/**
 * Deciding whether a generated file may be overwritten.
 *
 * `fix` writes test files into the user's repository. If one already exists it may
 * be a file the user edited by hand after a previous run, and overwriting it
 * silently loses their work — no test would fail, nothing would warn them.
 *
 * Two markers in every generated file make this decidable:
 *
 *   1. a "Generated by crucible" line, so a human knows where it came from
 *   2. a content hash of everything else, so we can tell whether it was edited
 *
 * If the file still carries our marker and the hash matches, it is untouched and
 * safe to replace. If the hash does not match, someone changed it: skip and say so.
 */

import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';

/** The marker every generated file starts with. */
export const GENERATED_MARKER = 'Generated by crucible';

/** A line carrying the hash, in either comment style. */
const HASH_LINE = /^[ \t]*(?:\/\/|#)[ \t]*crucible:hash[ \t]+([a-f0-9]{8,64})[ \t]*\r?\n?/gm;

/** Hash of the body with the hash line and trailing whitespace removed. */
export function contentHash(body) {
  const stripped = body.replace(HASH_LINE, '').replace(/\s+$/, '');
  return createHash('sha256').update(stripped).digest('hex').slice(0, 16);
}

/**
 * Append the hash line so a later run can detect edits.
 * @param {string} body
 * @param {'js'|'py'} style
 */
export function stamp(body, style = 'js') {
  const prefix = style === 'py' ? '#' : '//';
  // Hash exactly what gets written, minus the hash line, or a freshly written file
  // would compare unequal to itself on the next run.
  const trimmed = body.replace(/\s+$/, '');
  return `${trimmed}\n${prefix} crucible:hash ${contentHash(trimmed)}\n`;
}

/**
 * @param {string} path
 * @returns {Promise<'absent'|'generated-clean'|'generated-edited'|'user'>}
 */
export async function classifyTarget(path) {
  let text;
  try {
    text = await readFile(path, 'utf8');
  } catch {
    return 'absent';
  }

  const head = text.slice(0, 400);
  if (!/generated by crucible/i.test(head)) return 'user';

  const match = [...text.matchAll(HASH_LINE)].pop();
  if (!match) {
    // Written before hashes existed: treat as edit-risk, not as safe to replace.
    return 'generated-edited';
  }

  return match[1] === contentHash(text) ? 'generated-clean' : 'generated-edited';
}

/**
 * Should this write proceed?
 * @returns {Promise<{ write: boolean, reason?: string }>}
 */
export async function mayWrite(path, { force = false } = {}) {
  const state = await classifyTarget(path);

  if (state === 'absent') return { write: true };
  if (state === 'generated-clean') return { write: true };
  if (force) return { write: true, reason: 'overwriting an edited file because --force was given' };

  return {
    write: false,
    reason: state === 'user'
      ? 'a file with this name already exists and was not generated by crucible; left untouched (use --force to overwrite)'
      : 'this generated file was edited after it was written; left untouched (use --force to overwrite)',
  };
}
